def sample_report(tmp_path_factory):
    output_path = tmp_path_factory.mktemp("amostra") / "exemplo.json"
    process = run_cli_args(
        [
            "--input",
            str(PROJECT_ROOT / "data" / "exemplo-validacao.csv"),
            "--rates",
            str(PROJECT_ROOT / "data" / "taxas_cambio.csv"),
            "--output",
            str(output_path),
        ]
    )
    assert process.returncode == 0, process.stderr
    return json.loads(output_path.read_text(encoding="utf-8"))


def test_readme_has_the_three_sample_tables():
    summary, by_month, top_hotels = readme_tables()

    assert (len(summary), len(by_month), len(top_hotels)) == (7, 2, 5)


def test_summary_matches_readme(sample_report):
    summary_table = readme_tables()[0]

    assert sample_report["summary"] == {field: typed(value) for field, value in summary_table}


def test_by_month_matches_readme(sample_report):
    by_month_table = readme_tables()[1]
    expected = [
        {"month": month, "reservations": int(reservations), "room_nights": int(nights), "total_brl": total}
        for month, reservations, nights, total in by_month_table
    ]

    assert sample_report["by_month"] == expected


def test_top_hotels_match_readme(sample_report):
    top_table = readme_tables()[2]
    expected = [
        {"hotel_id": hotel_id, "hotel_name": name, "room_nights": int(nights), "total_brl": total}
        for hotel_id, name, nights, total in top_table
    ]

    assert sample_report["top_hotels"] == expected

