"""Teste de contrato: a amostra de validação bate com as tabelas do README.

As expectativas são lidas do próprio README (bloco AMOSTRA), sem cópia manual: o documento é a
especificação, e o teste quebra se o CLI divergir dele.
"""

import json
import re

import pytest
from cli_support import run_cli_args
from helpers import PROJECT_ROOT

SAMPLE_BLOCK = re.compile(r"<!-- AMOSTRA:INICIO -->(.*?)<!-- AMOSTRA:FIM -->", re.DOTALL)


def readme_tables() -> list[list[list[str]]]:
    """Tabelas markdown do bloco AMOSTRA, sem cabeçalho/separador e sem escapes (\\_ e `)."""
    block = SAMPLE_BLOCK.search((PROJECT_ROOT / "README.md").read_text(encoding="utf-8"))
    assert block, "bloco AMOSTRA não encontrado no README"

    tables: list[list[list[str]]] = []
    current: list[list[str]] = []
    for line in block.group(1).splitlines():
        if line.startswith("|"):
            cells = [cell.strip().replace("\\_", "_").strip("`") for cell in line.strip("|").split("|")]
            current.append(cells)
        elif current:
            tables.append(current[2:])
            current = []
    if current:
        tables.append(current[2:])
    return tables


def typed(value: str) -> int | str:
    """Contagens e noites são inteiros no JSON; dinheiro é string com 2 casas."""
    return value if "." in value or "-" in value else int(value)


@pytest.fixture(scope="module")
def sample_report(tmp_path_factory):
    output_path = tmp_path_factory.mktemp("amostra") / "exemplo.json"
    process = run_cli_args(
        [
            "--input",
            str(PROJECT_ROOT / "data" / "exemplo-validacao.csv"),
            "--rates",
            str(PROJECT_ROOT / "data" / "taxas_cambio.csv"),
            "--output",
            str(output_path),
        ]
    )
    assert process.returncode == 0, process.stderr
    return json.loads(output_path.read_text(encoding="utf-8"))


def test_readme_has_the_three_sample_tables():
    summary, by_month, top_hotels = readme_tables()

    assert (len(summary), len(by_month), len(top_hotels)) == (7, 2, 5)


def test_summary_matches_readme(sample_report):
    summary_table = readme_tables()[0]

    assert sample_report["summary"] == {field: typed(value) for field, value in summary_table}


def test_by_month_matches_readme(sample_report):
    by_month_table = readme_tables()[1]
    expected = [
        {"month": month, "reservations": int(reservations), "room_nights": int(nights), "total_brl": total}
        for month, reservations, nights, total in by_month_table
    ]

    assert sample_report["by_month"] == expected


def test_top_hotels_match_readme(sample_report):
    top_table = readme_tables()[2]
    expected = [
        {"hotel_id": hotel_id, "hotel_name": name, "room_nights": int(nights), "total_brl": total}
        for hotel_id, name, nights, total in top_table
    ]

    assert sample_report["top_hotels"] == expected

