        {"reservation_id": "R-1", "hotel_id": "H01", "amount": "100.00"},
        {"reservation_id": "R-2", "hotel_id": "H02", "amount": "40.00"},
        {"reservation_id": "R-3", "hotel_id": "H01", "amount": "10.00", "checkin_date": "2025-02-01"}
